import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"3D Packing · BPP3D: Scope and Learning Path","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/bpp3d/index.md","filePath":"frameworks/bpp3d/index.md"}'),o={name:"frameworks/bpp3d/index.md"};function r(d,e,s,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="_3d-packing-·-bpp3d-scope-and-learning-path" tabindex="-1">3D Packing · BPP3D: Scope and Learning Path <a class="header-anchor" href="#_3d-packing-·-bpp3d-scope-and-learning-path" aria-label="Permalink to &quot;3D Packing · BPP3D: Scope and Learning Path&quot;">​</a></h1><p>Cargo has three dimensions and weight. Choose bin types, orientations and positions, then produce a checkable, renderable loading plan. The first lesson uses cuboids rather than cylinders or complex support rules.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Role</th><th>Key Fields</th></tr></thead><tbody><tr><td>Cargo and package</td><td><code>Item</code> / <code>Package</code></td><td>Input</td><td>Dimensions, weight, materials and allowed orientations</td></tr><tr><td>Container type</td><td><code>BinType</code></td><td>Input</td><td>Geometry, load capacity and type identity</td></tr><tr><td>Candidate container layer</td><td><code>BinLayer</code></td><td>Intermediate</td><td>Container type, demand coverage and placement traces</td></tr><tr><td>Application service</td><td><code>ColumnGenerationApplicationService</code></td><td>Entry / validation</td><td>Master solves, generation, final selection and packing analysis</td></tr><tr><td>Final validation</td><td><code>PackingGeometryGuard</code></td><td>Entry / validation</td><td>Bounds, overlap and supported shape-path checks</td></tr><tr><td>Final packing result</td><td><code>PackingResult</code> / packing snapshot</td><td>Output</td><td>Physical bins, item positions, orientations and loading order</td></tr></tbody></table><p>A candidate column represents a selectable loading structure, not a completed final packing. Connect selection, physical placement and reporting.</p><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Kotlin and Rust Entry Points</p><p>Kotlin combines application requests, standard executors and a packing analyzer. Rust provides input-conversion and CSV interfaces with injected restricted-master and final-integer executors. Use the language-specific inputs and adapters shown in each lesson.</p></div><p>Start with a fixed bin and a small set of initial layers, then add generators, bin types and objective configuration.</p><p>This lesson uses the application service for restricted-master and final-integer execution, not a <code>Bpp3dMilp</code> switch. Start with initial layers with actual placements and physical bins, then expand orientations, types and budgets. See <a href="./business-scenario.html#entry-budget">entry and budget configuration</a>.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Cylinder support depends on axis and generation/support/final-validation paths; it does not imply arbitrary rotation in 3D.</li><li>Utilization must use the appropriate actual shape volume, not automatically its bounding cuboid.</li><li>The external renderer is separate. Producing DTOs does not launch a visualization page.</li><li>Inspect <code>finalSolved</code>, packing output and pricing diagnostics together, not just a nonempty candidate list.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-loading.html">your first 3D loading</a>, from candidate selection to final placements.</li><li>Add types, weight and costs, and explain the business meaning of objective weights.</li><li>See <a href="/ospf/examples/framework-example2.html">framework example 2</a> for integrated aircraft loading. Industry safety rules are not automatically included by using BPP3D.</li></ol><p>For LP, MILP, pricing and other algorithm terms, see the <a href="./../#terminology">terminology guide</a>.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp3d/README.md" target="_blank" rel="noreferrer">Kotlin entry points and shape paths</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp3d/README.md" target="_blank" rel="noreferrer">Rust entry points and domain rules</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./first-loading.html">Your First 3D Loading</a>. Then explore <a href="./business-scenario.html">Bin Types and Objectives</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',19)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
